package com.example.notitia.bridge

// The Rust core as the shared code sees it. On Android, Kotlin generated by UniFFI holds it; on the iPhone, a Swift
// class does. Swift cannot suspend, emit a Flow or throw one of our exceptions: every function here blocks, takes
// and returns plain values, and reports a failure as a value. A meeting, a change and an event cross as JSON text
// (ADR 0004), so a new one changes neither of the two classes that hold this interface.
interface NotitiaCore {
    // Reads the meetings of the folder and tells them to the listener before it returns. null once open.
    fun open(directory: String, listener: CoreListener): CoreFailure?

    // The whole meeting, lines included.
    fun meeting(id: String): CoreReply

    // null when the core read the change: what it changed, and a file it could not write, come as events.
    fun apply(change: String): CoreFailure?
}

// Called by the core on the thread that asked for a change, before its file is written. It must not ask for a change
// in turn, which would wait for itself, and it must not throw: nothing on the way back catches.
fun interface CoreListener {
    fun onEvent(event: String)
}

// One of the two is null. A class of its own rather than a generic one: Swift builds it, without a compiler here to
// check how.
class CoreReply(val text: String?, val failure: CoreFailure?)

// Invalid is a text the core does not read as a change, Broken a fault of the core itself or of its bridge: both
// are ours, never the user's.
enum class CoreFailure { NotFound, Unreadable, Invalid, Broken }
